import ("fmt"; "os"; "path/filepath"; "strings")
func Read(root, name string) ([]byte, error) {
 clean := filepath.Clean(name)
 if filepath.IsAbs(clean) || clean == ".." || strings.HasPrefix(clean, ".."+string(filepath.Separator)) { return nil, fmt.Errorf("invalid relative path") }
 return os.ReadFile(filepath.Join(root, clean))
}

